        "kind": "code",
        "code": "const a = world.vars.fieldA\nfor (let r = 0; r < a.rows; r = r + 1) {\n  for (let c = 0; c < a.cols; c = c + 1) {\n    if (r !== a.waterRow) {\n      golem.moveTo(a.x + c, a.z + r)\n      golem.harvest(\"wheat\", [a.x + c, 65, a.z + r])\n      golem.plant(\"wheat\", [a.x + c, 65, a.z + r])\n    }\n  }\n}",
