        "code": "interface Machine {\n  name: string\n  status: \"正常\" | \"过热\"\n  startSteps(): Step[]\n  stopSteps(): Step[]\n}\n\ntype Step = {\n  kind: \"on\" | \"off\"\n  pos: [number, number, number]\n  name: string\n  status: string\n}\n\n// 没有写 implements，形状对得上就能当 Machine 用（结构化类型）\nconst 一台: Machine = {\n  name: \"熔炉组\",\n  status: \"正常\",\n  startSteps: () => [],\n  stopSteps: () => [],\n}\ngolem.say(一台.name + \"：\" + 一台.status)",
